    /// <summary>
    /// The class chain, nearest first. Empty for something this table has never heard of, which
    /// cannot happen for a vanilla entry.
    /// </summary>
    public static BlockClass[] Of(Identifier id) {
        return Chains.TryGetValue(id, out BlockClass[]? chain) ? chain : [];
    }

    /// <summary>
    /// Whether the entry is, or inherits from, the given vanilla class. The name is the simple one
    /// (<c>Raider</c>, <c>DoorBlock</c>, <c>Monster</c>), because that is what the code being ported
    /// names and a package move upstream is not a behaviour change.
    /// </summary>
    public static bool Is(Identifier id, BlockClass className) {
        foreach (BlockClass name in Of(id)) {
            if (name == className) {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// The doors a mob can decide to open, <c>DoorBlock.type().canOpenByHand()</c>. It lives
    /// on the block set type rather than on any state, and it is the whole difference between
    /// a closed door the pathfinder routes through and one it treats as a wall.
    /// </summary>
    private static readonly HashSet<Identifier> HandOpenableDoors = [
        "minecraft:oak_door",
        "minecraft:spruce_door",
        "minecraft:birch_door",
        "minecraft:jungle_door",
        "minecraft:acacia_door",
        "minecraft:cherry_door",
        "minecraft:dark_oak_door",
        "minecraft:pale_oak_door",
        "minecraft:mangrove_door",
        "minecraft:bamboo_door",
        "minecraft:crimson_door",
        "minecraft:warped_door",
        "minecraft:copper_door",
        "minecraft:exposed_copper_door",
        "minecraft:weathered_copper_door",
        "minecraft:oxidized_copper_door",
        "minecraft:waxed_copper_door",
        "minecraft:waxed_exposed_copper_door",
        "minecraft:waxed_weathered_copper_door",
        "minecraft:waxed_oxidized_copper_door",
    ];

    public static bool DoorOpensByHand(Identifier block) {
        return HandOpenableDoors.Contains(block);
    }
